module square_wave_tb;

// === Global Sync Signal ===
reg llm_go_signal = 1;


    reg clk_tb = 0;        
    reg [8:0] freq_tb = 8'b0000100; 
    wire wave_out_tb;       
    integer ones_count = 0;  // Counter for consecutive ones
    integer error = 0;       // Error flag

    square_wave square_wave_inst (
        .clk(clk_tb),
        .freq(freq_tb),
        .wave_out(wave_out_tb)
    );

    initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

        // Monitor output
        // $monitor("Time: %0t | Clock: %b | Frequency: %d | Square Wave Output: %b | Error: %d", $time, clk_tb, freq_tb, wave_out_tb, error);

        // Simulate for a certain time
        repeat (200) begin
            if (wave_out_tb == 1) begin
                ones_count = ones_count + 1;
                if (ones_count > 8) begin
                    $display("Error: More than 8 consecutive ones detected at time %0t", $time);
                    error = 1;  // Set error flag
                    $finish;    // Stop the simulation
                end
            end else begin
                ones_count = 0;
            end
            #5; // Time delay between clock cycles
        end
        if (error == 0) begin
            $display("=========== Your Design Passed ===========");
        end
        $finish;  // Finish the simulation
    end

    always #5 clk_tb = ~clk_tb;





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "wave_out_tb,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", wave_out_tb);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests (Synchronization)
    wait(llm_go_signal == 1);

    $display("LLM_TEST: Starting deterministic mutation patterns.");

    // --- Test Case 1: Minimum Frequency (freq=1) ---
    // DUT Logic: if (count == freq - 1) -> if (count == 0).
    // Expectation: wave_out toggles every clock cycle.
    // Targets: Operator mutations (e.g., freq+1), Off-by-one errors.
    freq_tb = 8'h01;
    for (i = 0; i < 20; i = i + 1) begin
        @(posedge clk_tb);
    end

    // --- Test Case 2: Small Frequency (freq=2) ---
    // DUT Logic: if (count == 1).
    // Expectation: wave_out toggles every 2 clock cycles.
    freq_tb = 8'h02;
    for (i = 0; i < 20; i = i + 1) begin
        @(posedge clk_tb);
    end

    // --- Test Case 3: Boundary Condition - Zero (freq=0) ---
    // DUT Logic: if (count == 0 - 1) -> if (count == 255) [8-bit underflow].
    // Expectation: Count runs 0..255. Toggle every 256 cycles.
    // Targets: Underflow handling, bit-width assumptions.
    freq_tb = 8'h00;
    // Wait > 256 cycles to ensure wrap-around and toggle occur
    for (i = 0; i < 270; i = i + 1) begin
        @(posedge clk_tb);
    end

    // --- Test Case 4: Maximum Frequency (freq=255) ---
    // DUT Logic: if (count == 254).
    // Expectation: Count runs 0..254. Toggle every 255 cycles.
    // Targets: Boundary values, Max-1 logic.
    freq_tb = 8'hFF;
    for (i = 0; i < 270; i = i + 1) begin
        @(posedge clk_tb);
    end

    // --- Test Case 5: Alternating Bits (freq=0xAA) ---
    // Value: 170.
    // Targets: Stuck-at faults on bus lines, bit-select mutations.
    freq_tb = 8'hAA;
    for (i = 0; i < 180; i = i + 1) begin
        @(posedge clk_tb);
    end

    // --- Test Case 6: Alternating Bits Inverse (freq=0x55) ---
    // Value: 85.
    freq_tb = 8'h55;
    for (i = 0; i < 100; i = i + 1) begin
        @(posedge clk_tb);
    end

    // --- Restore State for Original TB ---
    // The original TB expects freq=4 to pass its internal "ones_count > 8" check.
    // We must restore this to prevent false failures in the Golden Model run.
    freq_tb = 8'd4;
    for (i = 0; i < 10; i = i + 1) begin
        @(posedge clk_tb);
    end

    // 3. Handover
    $display("LLM_TEST: Finished. Handing over control.");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

